  shadowUp: vec4<f32>,      // xyz camera up scaled by FOV, w tilt cosine
  shadowForward: vec4<f32>, // xyz camera forward, w strength
  shadowSun: vec4<f32>,     // xyz direction to sun, w cloud coverage
